macro_rules! Capabilities {
    () => {
        # [doc = " Common knowledge about the worktree that is needed across most interactions with the work tree"] # [cfg_attr (feature = "serde" , derive (serde :: Serialize , serde :: Deserialize))] # [derive (PartialEq , Eq , Debug , Hash , Ord , PartialOrd , Clone , Copy)] pub struct Capabilities { # [doc = " If `true`, the filesystem will consider the precomposed umlaut `ä` similar to its decomposed form `\"a\\u{308}\"` and consider them the same."] # [doc = " If `false`, the filesystem will only see bytes which means that the above example could live side-by-side."] # [doc = ""] # [doc = " Even though a filesystem that treats both forms the same will still reproduce the exact same byte sequence during traversal for instance,"] # [doc = " this might also mean that we see paths in their decomposed form (this happens when creating directory `ä` in MacOS Finder for example)."] # [doc = ""] # [doc = " If Git would store such decomposed paths in the repository, which only sees bytes, on linux this might mean the path will look strange"] # [doc = " at best, which is why it prefers to store precomposed unicode on systems where it matters, like MacOS and Windows."] # [doc = ""] # [doc = " For best compatibility, and with this value being `true`, we will turn decomposed paths and input like command-line arguments into their"] # [doc = " precomposed forms, so no decomposed byte sequences should end up in storage."] pub precompose_unicode : bool , # [doc = " If true, the filesystem ignores the case of input, which makes `A` the same file as `a`."] # [doc = " This is also called case-folding."] pub ignore_case : bool , # [doc = " If true, we assume the executable bit is honored as part of the files mode. If false, we assume the file system"] # [doc = " ignores the executable bit, hence it will be reported as 'off' even though we just tried to set it to be on."] pub executable_bit : bool , # [doc = " If true, the file system supports symbolic links and we should try to create them. Otherwise symbolic links will be checked"] # [doc = " out as files which contain the link as text."] pub symlink : bool , }
    };
}

Capabilities!()